const cache = new Map();

function getUserData(userId, callback) {
  if (cache.has(userId)) {
    // Case A: Synchronous execution
    callback(cache.get(userId));
  } else {
    // Case B: Asynchronous execution
    db.findById(userId, (err, user) => {
      cache.set(userId, user);
      callback(user);
    });
  }
}

