const crypto = require('crypto');

const start = Date.now();

function doHash(id) {
  // pbkdf2 is a CPU-intensive task offloaded to Libuv Thread Pool
  crypto.pbkdf2('password', 'salt', 100000, 512, 'sha512', () => {
    console.log(`Hash ${id} done:`, Date.now() - start);
  });
}

// Assuming the machine has 16 CPU cores
for (let i = 0; i < 8; i++) {
